@startuml

class City {
  + Name : string
}

class H2SLocation {
  + LocationID : string
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupRequest {
  + Description : string
  + RequestedDate : date
  + RequestedTime : time
}

class Item {
  + Description : string
  + Weight : float
  + Dimensions : string
  + IsFood : boolean
  + RFIDTag : string
  + Category : string
}

class Vehicle {
  + LicensePlate : string
  + StorageCapacity : float
}

class Route {
  + Date : date
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : string[]
}

class DistributionCenter {
  + Address : string
}

class Employee {
  + EmployeeID : string
  + Name : string
}

class Client {
  + Name : string
  + HomeAddress : string
  + NeededCategories : string[]
}

class FoodBank {
  + Address : string
}

H2SLocation "1" -- "1" City
H2SLocation "1" *-- "1" DistributionCenter

Resident "1" -- "0..*" PickupRequest : schedules
PickupRequest "1" *-- "1..*" Item

Vehicle "1" -- "0..*" Route
VolunteerDriver "1" -- "0..*" Route
Route "1" -- "1..*" PickupRequest

Item "1" -- "0..1" DistributionCenter : processed_at
Item "1" -- "0..1" FoodBank : delivered_to

Employee "1" -- "0..*" Item : examines
Employee "1" -- "0..*" Client : calls

Client "1" -- "0..*" Item : requests
Item "1" -- "0..*" Client : delivered_to

VolunteerDriver "1" -- "0..*" Client : delivers_to

@enduml

